$w=saas_wallet($uid);$plans=$db->query('SELECT * FROM saas_plans WHERE active=1 ORDER BY price_inr')->fetchAll(PDO::FETCH_ASSOC);$code=saas_referral_code($uid);
$ref=$db->prepare('SELECT COALESCE(SUM(commission_inr),0) FROM saas_referrals WHERE referrer_id=?');$ref->execute([$uid]);$earned=(float)$ref->fetchColumn();
require_once __DIR__.'/header.php';
