<div class="muted">Tool access</div><div class="num">Unlimited</div><p class="note">No usage limits.</p></div></div><section class="card" style="margin-top:16px"><h2>Earn with SmartToolz</h2><p class="muted">Share your referral link. When a referred user buys a paid plan, 20% of the eligible purchase is added to your referral wallet.</p><div class="ref"><input id="ref" readonly value="https://smarttoolz.in/smart-toolz/?ref=<?=urlencode($code)?>"><button class="btn" onclick="navigator.clipboard.writeText(document.getElementById('ref').value);this.textContent='Copied ✓'">Copy Link</button></div><p class="note">Total referral commissions recorded: ₹<?=number_format($earned,2)?>.</p></section><h2 style="margin:34px 0 8px">Plans</h2><p class="muted">Choose a plan for account benefits such as an ad-free experience.</p><div class="plans"><?php foreach($plans as $p): ?><div class="plan <?=$p['slug']==='pro'?'pro':''?>"><h3><?=htmlspecialchars($p['name'])?></h3><div class="price">₹<?=number_format((float)$p['price_inr'],0)?> <small class="muted">/month</small></div><p class="muted"><?=$p['ads_free']?'Ad-free experience':'Standard experience'?></p><?php if($p['slug']===$user['plan']): ?><span class="btn alt">Current plan</span><?php elseif((float)$p['price_inr']>0): ?><a class="btn" href="/smart-toolz/saas/upgrade.php?plan=<?=urlencode($p['slug'])?>">Choose Plan</a><?php else: ?><span class="btn alt">Free</span><?php endif;?></div><?php endforeach;?></div></main></body></html>